+void DXFimpl::addDxfEntitiesSource(const DRW_DxfEntitiesSource& source) {
+    _preserved.helixEntitiesSourceComplete =
+        source.status == DRW_DxfEntitiesSource::Status::Complete;
+    if (!_preserved.helixEntitiesSourceComplete) return;
+    for (const auto& record : source.records) {
+        for (const auto& field : record.groups) {
+            const int code = field.code();
+            const bool referenceCode = (code >= 320 && code <= 369)
+                || (code >= 390 && code <= 399) || code == 480
+                || code == 481 || code == 1005;
+            if (!referenceCode) continue;
+            if (field.type() != DRW_Variant::STRING) {
+                _preserved.helixEntitiesSourceComplete = false;
+                return;
+            }
+            std::size_t used = 0;
+            unsigned long parsed = 0;
+            try {
+                const std::string value = field.c_str();
+                parsed = std::stoul(value, &used, 16);
+                if (used != value.size() || parsed > UINT32_MAX) {
+                    _preserved.helixEntitiesSourceComplete = false;
+                    return;
+                }
+            } catch (...) {
+                _preserved.helixEntitiesSourceComplete = false;
+                return;
+            }
+            for (const auto& entry : _preserved.helices)
+                if (entry.second.source.handle == parsed)
+                    _preserved.helixEntitiesSourceHasReference = true;
+        }
+    }
+    std::cerr << "HELIX_ENTITIES_CENSUS complete=" << _preserved.helixEntitiesSourceComplete
+              << " inbound=" << _preserved.helixEntitiesSourceHasReference << "\n";
+}
