+static bool sameSplineGeometry(const lc::entity::Spline& a,
+                               const lc::entity::Spline& b) {
+    const auto equalPoints = [](const std::vector<lc::geo::Coordinate>& x,
+                                const std::vector<lc::geo::Coordinate>& y) {
+        if (x.size() != y.size()) return false;
+        for (std::size_t i = 0; i < x.size(); ++i)
+            if (x[i].x() != y[i].x() || x[i].y() != y[i].y()
+                || x[i].z() != y[i].z()) return false;
+        return true;
+    };
+    return a.degree() == b.degree() && a.flags() == b.flags()
+        && a.closed() == b.closed() && a.fitTolerance() == b.fitTolerance()
+        && a.knotPoints() == b.knotPoints()
+        && equalPoints(a.controlPoints(), b.controlPoints())
+        && equalPoints(a.fitPoints(), b.fitPoints())
+        && a.startTanX() == b.startTanX() && a.startTanY() == b.startTanY()
+        && a.startTanZ() == b.startTanZ() && a.endTanX() == b.endTanX()
+        && a.endTanY() == b.endTanY() && a.endTanZ() == b.endTanZ()
+        && a.nX() == b.nX() && a.nY() == b.nY() && a.nZ() == b.nZ();
+}
