#include <string>
struct Reader final : LC3CompatCheck {
  void addLine(const DRW_Line& line) override {
    for (const auto& v : line.extData)
      if (v && v->code() == 1005 && v->type() == DRW_Variant::STRING && v->stringEquals("33")) found=true;
  }
  void addHelix(const DRW_Helix* h) override { if(h) handle=h->handle; }
  bool found=false; unsigned handle=0;
};
int main(int argc,char**argv) { if(argc!=2) return 1; dxfRW input(argv[1]); Reader r; return input.read(&r,false)&&r.found&&r.handle==0x33u?0:2; }
